--- داده‌های در دسترس (فقط همین‌ها مبنا هستند؛ عدد بیرون از این‌ها اختراع نشود) ---
```json
{
  "data_catalog": [
    {
      "dataset": "budget_actual",
      "description": "بودجهٔ مصوب و عملکرد واقعی به تفکیک سرفصل و ماه",
      "dimensions": [
        "line_item",
        "month"
      ],
      "measures": [
        "budget_m",
        "actual_m"
      ]
    },
    {
      "dataset": "rolling_forecast",
      "description": "پیش‌بینی متحرک درآمد و هزینه به تفکیک ماه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "forecast_revenue_m",
        "forecast_cost_m"
      ]
    },
    {
      "dataset": "capex_plan",
      "description": "برنامهٔ سرمایه‌ای: مصوب، مصرف‌شده، پیشرفت",
      "dimensions": [
        "project",
        "month"
      ],
      "measures": [
        "approved_m",
        "spent_m",
        "progress_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "budget_variance",
      "description": "انحراف بودجه",
      "formula": "(واقعی منهای بودجه) تقسیم بر بودجه",
      "unit": "درصد",
      "dimensions": [
        "line_item"
      ]
    },
    {
      "metric": "burn_rate",
      "description": "نرخ مصرف نقدینگی",
      "formula": "خالص هزینهٔ ماهانه",
      "unit": "میلیارد/ماه",
      "dimensions": [
        "month"
      ]
    }
  ],
  "business_context": [
    "چرخهٔ بودجه‌ریزی سالانه از مهر آغاز می‌شود",
    "پیش‌بینی متحرک دوازده‌ماهه هر فصل به‌روزرسانی می‌شود",
    "هیئت‌مدیره گزارش انحراف ماهانه می‌خواهد"
  ]
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "budget_actual",
    "filters": {
      "period": "this_month"
    }
  }
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "rolling_forecast",
    "filters": {
      "horizon": "next_quarter"
    }
  }
}
```

